#!/usr/bin/env python3
"""Run C1 Unit06 recalibration with narrow depth extensions that avoid new target forms."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c1_unit06.py')
text=SOURCE.read_text(encoding='utf-8')
patches={
"القراءة المنضبطة تشرح لماذا يعد عنصر ما وسيلة أو قيدًا، وما الأدلة التي تدعم هذا التصنيف، وأي وظيفة يجب اختبارها عندما تتغير الظروف.''',":"القراءة المنضبطة تشرح لماذا يعد عنصر ما وسيلة أو قيدًا، وما الأدلة التي تدعم هذا التصنيف، وأي وظيفة يجب اختبارها عندما تتغير الظروف. وفي مراجعة لاحقة قارن الاتحاد بين اجتماع حضوري واجتماع بعيد باستخدام القائمة نفسها من الوظائف، وسجل حالات التأخير وفقد الصوت وصعوبة الاعتراض في الوقت المناسب. لم يكن الهدف إعلان تفوق وسيلة مطلقًا، بل اختبار ما إذا كانت البدائل تحقق الحق بصورة يمكن الاعتماد عليها. وعندما ظهرت مشكلة في توقيت التصويت، عدلت الإجراءات بدل إعادة الجدل إلى كلمة المكان وحدها. بهذا أصبحت الوظيفة معيارًا يمكن اختباره لا ذريعة مفتوحة لتجاوز الصياغة.''',",
"القاعدة العامة قد تبقى كما هي، لكن تصميم التنفيذ يجب أن يسمح لمن يخضع لها بفرصة عملية معقولة للامتثال.''',":"القاعدة العامة قد تبقى كما هي، لكن تصميم التنفيذ يجب أن يسمح لمن يخضع لها بفرصة عملية معقولة للامتثال. ثم طلبت اللجنة من الإدارة مقارنة من علموا بالقناة الاحتياطية بمن لم يعلموا بها، لأن نشر الخيار جزء من فعاليته. أظهرت المقارنة أن الإعلان المتأخر يترك فرقًا حتى عندما تكون الأداة متاحة تقنيًا. لذلك صارت أي وسيلة بديلة تقيم من حيث وجودها ووضوحها وزمن استخدامها معًا. كما سجلت المكتبة الشكاوى قبل التعديل وبعده لتفحص هل انتقل العائق إلى خطوة أخرى من العملية بدل أن يختفي.''',",
"وكلما كانت اللغة المفتوحة أوسع، زادت أهمية الأسباب والمراجعة والأمثلة المنشورة.''',":"وكلما كانت اللغة المفتوحة أوسع، زادت أهمية الأسباب والمراجعة والأمثلة المنشورة. كما قارنت اللجنة قرارات موظفين مختلفين في وقائع متقاربة من دون الكشف عن أسماء أصحابها. إذا اختلفت النتائج، طلبت تحديد العامل الواقعي الذي يبرر الفرق. في حالتين لم يوجد عامل واضح، فاستعملت اللجنة النتيجة لتدريب الموظفين وتعديل نموذج الأسباب. لم يكن الهدف توحيد كل حكم آليًا، بل منع مساحة الحكم من أن تتحول مع الزمن إلى قواعد شخصية لا يعرفها الجمهور ولا يستطيع توقعها.''',",
"إبقاء السؤالين منفصلين يساعد المؤسسة على معرفة هل تحتاج إلى تعديل السياسة أم إلى اتباع طريق أعلى لتغيير القيد نفسه.''',":"إبقاء السؤالين منفصلين يساعد المؤسسة على معرفة هل تحتاج إلى تعديل السياسة أم إلى اتباع طريق أعلى لتغيير القيد نفسه. وفي تمرين داخلي أعطيت مجموعة من المراجعين قاعدة محبوبة لكنها صادرة بلا سند كاف، وقاعدة غير محبوبة لكنها تقع بوضوح داخل التفويض. ساعد المثال على كشف ميل المشاركين إلى خلط تقييم النتيجة بتقييم مصدر السلطة. ثم طلب منهم كتابة العلاج المناسب لكل مشكلة: تعديل محتوى الأولى لا يصحح نقص السلطة، كما أن كراهية الثانية لا تجعلها باطلة من هذا الباب وحده.''',",
"قالت اللجنة إن التناسب ليس إيجاد منتصف عددي بين طرفين. هو حجة منظمة تربط شدة الوسيلة بقوة الحاجة، وتبحث عن بدائل واقعية، وتحسب عبء الخطأ والزمن، وتترك طريقًا للمراجعة عندما تتغير الوقائع.''',":"قالت اللجنة إن التناسب ليس إيجاد منتصف عددي بين طرفين. هو حجة منظمة تربط شدة الوسيلة بقوة الحاجة، وتبحث عن بدائل واقعية، وتحسب عبء الخطأ والزمن، وتترك طريقًا للمراجعة عندما تتغير الوقائع. ثم أجرت المؤسسة تجربة قصيرة للحزمة الأخف وقاست الفقد والأخطاء ووقت الموظفين قبل توسيعها. عندما حققت معظم الحماية المتوقعة، أصبح من الأصعب تبرير إجراء أشد على الجميع. ولو فشلت التجربة، لكان ذلك دليلًا جديدًا يعيد فتح المقارنة. بهذا لم تبق البدائل افتراضات نظرية؛ أصبحت نتائج قابلة للفحص تدخل مباشرة في تقدير الحاجة والعبء.''',",
"قالت إن التدريب المتقدم لا يهدف إلى تعليم قاعدة سحرية، بل إلى جعل القارئ يميز أسئلة المعنى والغاية والوصول والسلطة وشدة التدخل ثم يعيد جمعها في حجة واضحة.''',":"قالت إن التدريب المتقدم لا يهدف إلى تعليم قاعدة سحرية، بل إلى جعل القارئ يميز أسئلة المعنى والغاية والوصول والسلطة وشدة التدخل ثم يعيد جمعها في حجة واضحة. وأضاف المدرس تمرينًا يغير واقعة واحدة في كل مرة: قوة العبارة، أو مقدار العائق، أو مصدر التفويض، أو شدة الإجراء. طلب من الطلاب تحديد أي جزء من التحليل يجب أن يتغير وأي أجزاء تبقى ثابتة. ساعد ذلك على منع استبدال الحجة كلها كلما تغيرت النتيجة، وأظهر أن القرار الجيد يمكن تحديثه موضعيًا عندما نعرف أي مقدمة هي التي تغيرت.''',",
}
for old,new in patches.items():
    assert text.count(old)==1, f'expected one retry insertion point: {old[:40]!r}'
    text=text.replace(old,new)
exec(compile(text,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
